from taf.collectors.core import CommandCollector


class SimpleCollector(CommandCollector):
    """
    Collect files selected by directory path and filename pattern via SCP
    or SFTP. The filename pattern is a regular expression.
    """

    def __init__(
            self,
            dir_path,
            file_pattern=".*",
            options="",
            target_file_name=None,
            **kwargs):
        super().__init__(**kwargs)
        self._dir_path = dir_path
        self._search_options = options
        self._search_pattern = file_pattern
        self._log_name = f"files_{self._name}"
        self._log_dir = f"/tmp/{self._log_name}"
        self._target_file_name = target_file_name
        if target_file_name is None:
            self._target_file_name = self._log_name

    def _copy_files_and_tgz_them(self):
        cd_cmd = f"cd '{self._dir_path}'"
        find_cmd = "find . -type d -o -regex '{regex}' {options}".format(
            regex=self._search_pattern,
            options='\\( ' + self._search_options + ' \\)'
                    if self._search_options else ''
        )
        cp_cmd = f"cp -a --parents '{{}}' '{self._log_dir}'"
        cmd = rf'{self._sudo_prefix}bash -c "{cd_cmd}; {find_cmd} -exec {cp_cmd} \; ; :"'
        self._tool_executor.execute(cmd.encode(), use_tty=True)
        self._tool_executor.execute(
            f"{self._sudo_prefix}tar czf {self._log_dir}.tgz -C {self._log_dir} .".encode(),
            use_tty=True)

    def _setup(self):
        self._sudo_prefix = self._tool_executor.sudo_prefix()
        self._tool_executor.execute(
            f"{self._sudo_prefix}mkdir -p {self._log_dir}".encode(),
            use_tty=True)

    def _teardown(self):
        self._tool_executor.execute(
            f"{self._sudo_prefix}rm -rf {self._log_dir}".encode(),
            use_tty=True)
        self._tool_executor.execute(
            f"{self._sudo_prefix}rm -f {self._log_dir}.tgz".encode(),
            use_tty=True)

    def _collect(self, target_dir):
        self._copy_files_and_tgz_them()
        self._file_getter.get_file(
            source_path=f"{self._log_dir}.tgz",
            target_path=f"{target_dir}/{self._target_file_name}.tgz")
